head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > chooseOptionLabel]<br/>Column 의 SelectBox 에 추가된 '선택 안내' 아이템의 Label 값을 설정합니다.",
    "validation" : [
        "Column 의 chooseOption=true 이고 inputType='select' 인 경우에 동작합니다.",
        "속성값 설정 시, '선택 안내' 아이템의 Label 값을 설정합니다.",
        "값을 설정하지 않으면 '-선택-'이 적용됩니다.",
        "changeChooseOption() 메소드를 사용하여 Label 값을 수정할 수 있습니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  - 전제 조건(inputType, chooseOption)은 충족값, 검증 대상 속성은 의미 있는 값으로 초기 선택
    con_inputType.setValue("select");
    con_chooseOption.setValue("true");
    con_chooseOptionLabel.setValue("지역을 선택하세요");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name   : 비교용 text Column
//  - region : 검증 대상 Column (아이템 서울(S) / 부산(B) / 대구(D) 정적 정의, Row 2 는 빈 값)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] region Column 아이템 : 서울(S) / 부산(B) / 대구(D), Row 2 는 빈 값\n[절차] Row 0 region 셀 더블클릭 -> 목록 첫 아이템 확인 -> chooseOptionLabel 확인\n[확인] 아이템 리스트 [0] Label 과 Row 2 셀 표시값"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cInputType = con_inputType.getValue();
    let cChooseOption = con_chooseOption.getValue();
    let cChooseOptionLabel = con_chooseOptionLabel.getValue();

    let attrRegion = ' inputType="' + cInputType + '"';
    attrRegion += ' chooseOption="' + cChooseOption + '"';
    // 특수문자(<, >, &, 큰따옴표) 포함 값은 XML 속성값으로 넘기기 위해 엔티티로 변환 (화면에는 원래 문자로 표시되어야 함)
    let xmlLabel = cChooseOptionLabel.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    attrRegion += (cChooseOptionLabel === '') ? '' : ' chooseOptionLabel="' + xmlLabel + '"';

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "region" : "S" },
        { "name" : "김철수", "region" : "B" },
        { "name" : "이영희", "region" : "" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column2" value="region"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="300" style="" id="region" value=""' + attrRegion + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// '선택 안내' 아이템 Label / 빈 값 셀 표시값 확인
//  - validation 1 : inputType / chooseOption 조건별 아이템 리스트 첫 아이템과 Row 2 셀 표시값 대비
//  - validation 2, 3 : 아이템 리스트 [0] Label 과 Row 2(빈 값) 셀 표시값
//  - validation 4 : setColumnChooseOption 실행 후 동일 항목 재확인
scwin.btn_checkChooseOptionLabel_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    // 셀 편집 시 생성되는 region Column 의 선택 아이템 편집기 (selectbox)
    let editor = $p.getComponentById("G_" + target1.id + "___selectbox_region");
    if (editor) {
        let arrItem = editor.getItemArray().map(function (item, idx) {
            return "[" + idx + "] " + item.label + " (" + item.value + ")";
        });
        bottom.setReturnValue("아이템 리스트 : " + arrItem.join(" / "));
    }

    let td = document.querySelector("td[id*='" + target1.id + "_cell_2_1']");
    let cellText = td ? td.textContent : "";
    bottom.setReturnValue("Row 2(빈 값) 셀 표시값 : " + (cellText === "" ? "(빈 값)" : cellText));
}



// validation 4 : 가이드의 changeChooseOption() 은 gridView 에 없는 메소드(selectbox 메소드)라
//  gridView 의 대응 메소드 setColumnChooseOption(columnInfo, chooseOptionValue, chooseOptionLabel) 로 Label 변경
//  (Value 는 기본값 빈 문자열 유지)
scwin.btn_setColumnChooseOption_onclick = function () {
    let label = par_chooseOptionLabel.getValue();
    target1.setColumnChooseOption("region", "", label);
    scwin.btn_checkChooseOptionLabel_onclick();
}
